<?php
if(getenv('INSTAPASS_ISOLATED_TEST')!=='yes')throw new RuntimeException('Isolated test only.');
function ipl_test($yes,$why){if(!$yes)throw new RuntimeException($why);}
$groups=ipl_groups();$credits=count(array_filter($groups,'ipl_credit'));ipl_test(count($groups)===($credits?7:5),'Expected product families');wp_set_current_user(0);$offers=0;
foreach($groups as $g){$html=ipl_card($g);ipl_test(substr_count($html,'<article ')===1,'One tile per family');if(ipl_credit($g)){ipl_test(array_keys($g['offers'])===range(50,500,25),'Every $25 credit face configured');ipl_test(strpos($html,'step="25"')!==false&&strpos($html,'Credits expire monthly')!==false,'Credit slider and expiry');}else ipl_test(substr_count($html,'type="radio"')===count($g['offers']),'Every duration selectable');ipl_test(strpos($html,'Pricing coming soon')!==false&&strpos($html,'add-to-cart')===false,'Price and purchase hold');foreach($g['offers'] as $m=>$o){$offers++;$p=wc_get_product($o['id']);ipl_test(!$p->is_purchasable(),'Held offer must reject direct purchasing');}}
ipl_test($offers===($credits?51:13),'Expected offer records');
$cart=WC()->cart;$cart->empty_cart();$p=wc_get_product(29);ipl_test(!$cart->add_to_cart(29),'Forged add to cart rejected');$retired=wc_get_product(34);ipl_test($retired->get_status()==='draft'&&!$retired->is_purchasable(),'Retired product cannot sell');
// Exercise future pricing approval without changing production or retaining fixture pricing.
$first=$groups[0]['offers'][6]['id'];$p=wc_get_product($first);$p->set_regular_price('45.00');$p->set_price('45.00');$p->save();$test=$groups;$test[0]['offers'][6]['ready']=true;update_option('instapass_launch_groups',$test,false);$p=wc_get_product($first);ipl_test($p->is_purchasable(),'Approved priced duration becomes buyable');$html=ipl_card($test[0]);ipl_test(strpos($html,'add-to-cart='.$first)!==false,'Buy link targets selected duration');$p->set_regular_price('');$p->set_price('');$p->save();update_option('instapass_launch_groups',$groups,false);
$credit_checks=false;if($credits){$g=$groups[5];$id=$g['offers'][75]['id'];$p=wc_get_product($id);$item=new WC_Order_Item_Product();$item->set_product($p);$item->set_quantity(1);do_action('woocommerce_checkout_create_order_line_item',$item,'fixture',array('data'=>$p,'quantity'=>1),new WC_Order());ipl_test($item->get_meta('Credit balance')==='$75'&&$item->get_meta('Credit expiry')==='Monthly','Credit face and expiry persist in order item');$rows=apply_filters('woocommerce_get_item_data',array(),array('data'=>$p,'quantity'=>1));ipl_test(strpos(wp_json_encode($rows),'Monthly')!==false,'Cart shows credit expiry');$credit_checks=true;}
$admins=get_users(array('role'=>'administrator','number'=>1));wp_set_current_user($admins[0]->ID);ob_start();ipl_admin();$admin=ob_get_clean();ipl_test(substr_count($admin,'Price reviewed and ready')===$offers,'Owner can approve each option separately');wp_set_current_user(0);
echo wp_json_encode(array('result'=>'pass','families'=>count($groups),'offers'=>$offers,'credit_order_metadata'=>$credit_checks,'direct_purchase_blocked'=>true,'future_price_approval'=>true,'native_owner_controls'=>true));
